#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    long long factorial = 1;
    for (int i = 2; i <= n; i++) {
        factorial *= i;
    }
    int zeros = 0;
    long long temp = factorial;
    while (temp > 0 && temp % 10 == 0) {
        zeros++;
        temp /= 10;
    }
    cout << "Factorial: " << factorial << endl;
    cout << "Trailing zeros: " << zeros << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;
    int count = 0;
    cout << "Primes:";
    for (int n = a; n <= b; n++) {
        if (n < 2) {
            continue;
        }
        bool isPrime = true;
        int d = 2;
        while (d * d <= n) {
            if (n % d == 0) {
                isPrime = false;
                break;
            }
            d++;
        }
        if (isPrime) {
            cout << " " << n;
            count++;
        }
    }
    if (count == 0) {
        cout << " none";
    }
    cout << endl;
    cout << "Count: " << count << endl;
    return 0;
}

