#include <iostream>
using namespace std;

int main() {
    int n;
    long long balance;
    cin >> n >> balance;
    int processed = 0;
    int record = 1;
    do {
        long long amount;
        cin >> amount;
        if (amount == -1) {
            cout << "Cancelled at record " << record << endl;
            break;
        }
        if (amount <= balance) {
            balance -= amount;
            cout << "TXN " << record << ": Approved, balance " << balance << endl;
        } else {
            cout << "TXN " << record << ": Declined" << endl;
        }
        processed++;
        record++;
    } while (record <= n);
    cout << "Processed: " << processed << endl;
    cout << "Final balance: " << balance << endl;
    return 0;
}

