#include <iostream>
using namespace std;

int main() {
    int percent, drain, cutoff;
    cin >> percent >> drain >> cutoff;
    int cycles = 0;
    do {
        percent -= drain;
        if (percent < 0) {
            percent = 0;
        }
        cycles++;
        cout << "Cycle " << cycles << ": " << percent << "%" << endl;
    } while (percent > cutoff);
    cout << "Cycles used: " << cycles << endl;
    cout << "Final charge: " << percent << "%" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int denoms[6] = {500, 100, 50, 10, 5, 1};
    long long totals[6] = {0, 0, 0, 0, 0, 0};
    int served = 0;
    int customer = 1;
    while (customer <= n) {
        long long amount;
        cin >> amount;
        if (amount == -1) {
            break;
        }
        long long remaining = amount;
        long long counts[6] = {0, 0, 0, 0, 0, 0};
        for (int d = 0; d < 6; d++) {
            counts[d] = remaining / denoms[d];
            remaining %= denoms[d];
            totals[d] += counts[d];
        }
        cout << "Customer " << customer << ": " << amount << endl;
        cout << "  500 x " << counts[0]
             << ", 100 x " << counts[1]
             << ", 50 x " << counts[2]
             << ", 10 x " << counts[3]
             << ", 5 x " << counts[4]
             << ", 1 x " << counts[5] << endl;
        served++;
        customer++;
    }
    cout << "Denomination totals:" << endl;
    for (int d = 0; d < 6; d++) {
        cout << denoms[d] << ": " << totals[d] << endl;
    }
    cout << "Customers served: " << served << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int days, stops;
    cin >> days >> stops;
    long long grand = 0;
    int busiestDay = 1;
    long long bestTotal = -1;
    for (int day = 1; day <= days; day++) {
        long long dayTotal = 0;
        int longestStop = 1;
        int longestVal = -1;
        for (int stop = 1; stop <= stops; stop++) {
            int km;
            cin >> km;
            dayTotal += km;
            if (km > longestVal) {
                longestVal = km;
                longestStop = stop;
            }
        }
        grand += dayTotal;
        cout << "Day " << day << ": total " << dayTotal
             << " km, longest stop " << longestStop
             << " (" << longestVal << " km)" << endl;
        if (dayTotal > bestTotal) {
            bestTotal = dayTotal;
            busiestDay = day;
        }
    }
    double average = (double)grand / days;
    cout << "Total distance: " << grand << " km" << endl;
    cout << fixed << setprecision(2) << "Average per day: " << average << " km" << endl;
    cout << "Busiest day: " << busiestDay << " (" << bestTotal << " km)" << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int scores[2000];
    int count = 0;
    long long sum = 0;
    int s;
    cin >> s;
    while (s != -1) {
        scores[count] = s;
        count++;
        sum += s;
        cin >> s;
    }
    int highest = scores[0];
    int lowest = scores[0];
    for (int i = 1; i < count; i++) {
        if (scores[i] > highest) {
            highest = scores[i];
        }
        if (scores[i] < lowest) {
            lowest = scores[i];
        }
    }
    double average = (double)sum / count;
    int above = 0;
    for (int i = 0; i < count; i++) {
        if (scores[i] > average) {
            above++;
        }
    }
    cout << "Players: " << count << endl;
    cout << "Highest: " << highest << endl;
    cout << "Lowest: " << lowest << endl;
    cout << fixed << setprecision(2) << "Average: " << average << endl;
    cout << "Above average: " << above << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string code;
    cin >> code;
    long long combinations = 1;
    for (int i = 0; i < (int)code.length(); i++) {
        int digit = code[i] - '0';
        int letters;
        if (digit == 7 || digit == 9) {
            letters = 4;
        } else if (digit == 0 || digit == 1) {
            letters = 0;
        } else {
            letters = 3;
        }
        if (letters == 0) {
            cout << "Digit " << digit << ": no letters" << endl;
        } else {
            cout << "Digit " << digit << ": " << letters << " letters" << endl;
        }
        combinations *= letters;
    }
    cout << "Total letter combinations: " << combinations << endl;
    return 0;
}

